import{_ as t,o as u,c as i,a3 as l,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const s="/bilder/schueler/dokumentenverwaltung-druck-auswahl.png",a="/bilder/schueler/dokumentenverwaltung-reiter.png",o="/bilder/schueler/dokumentenverwaltung-dokumente.png",w=JSON.parse('{"title":"Dokumente eines Schulkindes ablegen und aufrufen","description":"","frontmatter":{"title":"Dokumente eines Schulkindes ablegen und aufrufen","source_pageid":1355,"source_revision":6589},"headers":[],"relativePath":"schild3/schueler/dokumentenverwaltung-schueler.md","filePath":"schild3/schueler/dokumentenverwaltung-schueler.md"}'),d={name:"schild3/schueler/dokumentenverwaltung-schueler.md"};function g(c,r,h,m,k,p){return u(),i("div",null,[...r[0]||(r[0]=[l('<h1 id="dokumente-eines-schulkindes-ablegen-und-aufrufen" tabindex="-1">Dokumente eines Schulkindes ablegen und aufrufen <a class="header-anchor" href="#dokumente-eines-schulkindes-ablegen-und-aufrufen" aria-label="Permalink to &quot;Dokumente eines Schulkindes ablegen und aufrufen&quot;">​</a></h1><p>Nutzen Sie die aktivierte Dokumentenverwaltung, um erzeugte Reportausgaben im zugehörigen Schülerordner abzulegen und vorhandene Dokumente aufzurufen.</p><p>Wurde die Dokumentenverwaltung über <em>Verwaltung ➜ Einstellungen ➜ Globale Einstellungen ➜ Dokumentenverwaltung</em> aktiviert, steht nun ein weiterer Reiter <strong>Dokumentenverwaltung</strong> bei den Schülern zur Verfügung.</p><p>Konsultieren Sie hierzu den Artikel <a href="/reporting/zeugnisformulare/dokumentenverwaltung-und-zeugnisarchivierung.html">Reportausgaben und Zeugnisse archivieren</a>.</p><p><a href="/bilder/schueler/dokumentenverwaltung-druck-auswahl.png"><img src="'+s+'" alt="Auswahl, ob ein Report nur zum Drucker, zum Drucker und in die Dokumentenverwaltung oder nur in die Dokumentenverwaltung gesendet werden soll." loading="lazy"></a></p><p><em>Auswahl, ob ein Report nur zum Drucker, zum Drucker und in die Dokumentenverwaltung oder nur in die Dokumentenverwaltung gesendet werden soll.</em></p><p><strong>Reportausgaben ablegen</strong></p><p>Die Optionen der Dokumentenablage erscheinen beim Erzeugen eines Reports, wenn dieser die <strong>Datenquelle Schueler</strong> und eine <strong>Gruppe Schueler.ID</strong> enthält.</p><ul><li><strong>Drucker mit Archivierung</strong> sendet den Report zu einem Drucker und zusätzlich wird ein PDF im Ordner des Schülers der Dokumentenablage erzeugt.</li><li><strong>nur Archivierung (in Dokumentenverwaltung)</strong> erzeugt nur das PDF. So lässt sich zum Beispiel auch ein schon gedruckter Report noch einmal nach-archivieren.</li></ul><p><a href="/bilder/schueler/dokumentenverwaltung-reiter.png"><img src="'+a+'" alt="der Reiter Schüler ➜ Dokumentenverwaltung." loading="lazy"></a></p><p><em>der Reiter Schüler ➜ <strong>Dokumentenverwaltung</strong>.</em></p><p>Über den Reiter <em>Schüler</em> <strong>Dokumentenverwaltung</strong> erreichen Sie den Unterordner des Schülers und sehen die dort abgelegten Dokumente.</p><p><a href="/bilder/schueler/dokumentenverwaltung-dokumente.png"><img src="'+o+'" alt="Die Dokumente in der Dokumentenverwaltung eines Schülers." loading="lazy"></a></p><p><em>Die Dokumente in der Dokumentenverwaltung eines Schülers.</em></p><p>Über diesen Explorer lassen sich wie in Windows alle abgelegten Dokumente direkt aufrufen.</p><p>Mit der <code>Rechten Maustaste</code> kann das übliche Kontextmenü von Windows geöffnet werden. So lässt sich zum Beispiel auch ein eigenes Explorer-Fenster öffnen.</p>',16),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Für die Dokumentenablage gilt keine einheitliche gesetzliche Zehnjahresfrist. Nach "),e("a",{href:"https://bass.schule.nrw/101.htm",target:"_blank",rel:"noreferrer"},"§ 9 VO-DV I"),n(" unterscheiden sich die Fristen nach Dokumentart: Zweitschriften von Abgangs- und Abschlusszeugnissen 50 Jahre, Schülerstammblätter 20 Jahre, die dort genannten übrigen Zeugnis- und Prüfungsunterlagen 10 Jahre, alle übrigen Daten 5 Jahre. Vor einer Löschung sind Dokumentart, Fristbeginn und gegebenenfalls die Anbietung an das zuständige Archiv zu berücksichtigen. Die Programmauswahl ersetzt diese Zuordnung nicht.")])],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Dokumentenverwaltung_(Sch%C3%BCler)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 6589.")],-1)])])}const b=t(d,[["render",g]]);export{w as __pageData,b as default};
